ee:message.ee:set-payload:
%dw 2.0
output multipart/form-data
---
{
    parts: {
        username: {
            headers : {"Content-Type": "text/plain"},
            content: p('salesforce.rest-token.username')
        },
        password: {
        	headers : {"Content-Type": "text/plain"},
            content: p('salesforce.rest-token.password')
        },
        grant_type: {
        	headers : {"Content-Type": "text/plain"},
            content: p('salesforce.rest-token.grant_type')
        },
        client_id: {
        	headers : {"Content-Type": "text/plain"},
            content: p('salesforce.rest-token.client_id')
        },
        client_secret: {
        	headers : {"Content-Type": "text/plain"},
            content: p('salesforce.rest-token.client_secret')
        }
    }
}
